5	namespace PhpAiToolkit\PhpStan\Rule;
6	
7	use PhpAiToolkit\PhpStan\Rule\ForbiddenNamespace\ForbiddenNamespacePrefixes;
8	use PHPStan\Analyser\Scope;
9	use PHPStan\Rules\IdentifierRuleError;
10	use PHPStan\Rules\Rule;
11	use PHPStan\Rules\RuleErrorBuilder;
12	
13	/**
14	 * Forbids configured namespace prefixes.
15	 *
16	 * @implements Rule<\PhpParser\Node\Stmt\Namespace_>
17	 */
18	final class ForbiddenNamespaceRule implements Rule
19	{
20	    /** @readonly */
21	    private ForbiddenNamespacePrefixes $forbiddenNamespacePrefixes;
22	
23	    /**
24	     * @param list<string> $forbiddenNamespacePrefixes namespace prefixes to forbid
25	     */
26	    public function __construct(array $forbiddenNamespacePrefixes = [])
27	    {
28	        $this->forbiddenNamespacePrefixes = new ForbiddenNamespacePrefixes($forbiddenNamespacePrefixes);
29	    }
30	
31	    /**
32	     * @return class-string<\PhpParser\Node\Stmt\Namespace_>
33	     */
34	    public function getNodeType(): string
35	    {
36	        return \PhpParser\Node\Stmt\Namespace_::class;
37	    }
38	
39	    /**
40	     * @param \PhpParser\Node\Stmt\Namespace_ $node
41	     * @return list<IdentifierRuleError>
42	     */
43	    public function processNode(\PhpParser\Node $node, Scope $scope): array
44	    {
45	        if ($node->name === null) {
46	            return [];
47	        }
48	
49	        $namespace = $node->name->toString();
50	        $prefix = $this->forbiddenNamespacePrefixes->matchingPrefix($namespace);
51	
52	        if ($prefix === null) {
53	            return [];
54	        }
55	
56	        return [
57	            RuleErrorBuilder::message(
58	                sprintf(
59	                    'Move code out of namespace "%s". Use a namespace outside forbidden test prefix "%s", or inline setup in each test.',
60	                    $namespace,
61	                    $prefix
62	                )
63	            )
64	                ->identifier('customRules.forbiddenNamespace')
65	                ->line($node->getStartLine())
66	                ->build(),
67	        ];
68	    }
69	}
