3	declare(strict_types=1);
4	
5	namespace PhpAiToolkit\PhpStan\Rule;
6	
7	use PhpAiToolkit\PhpStan\Rule\NoNonPublicMethod\NonPublicMethodErrorBuilder;
8	use PhpAiToolkit\PhpStan\Rule\NoNonPublicMethod\ProtectedMethodPolicy;
9	use PHPStan\Analyser\Scope;
10	use PHPStan\Rules\IdentifierRuleError;
11	use PHPStan\Rules\Rule;
12	
13	/**
14	 * Reports private methods and non-extension protected methods.
15	 *
16	 * @implements Rule<\PhpParser\Node\Stmt\ClassLike>
17	 */
18	final class NoNonPublicMethodRule implements Rule
19	{
20	    /** @readonly */
21	    private ProtectedMethodPolicy $protectedMethodPolicy;
22	
23	    /** @readonly */
24	    private NonPublicMethodErrorBuilder $errorBuilder;
25	
26	    /**
27	     * Creates the non-public method rule from its design collaborators.
28	     */
29	    public function __construct(
30	        ?ProtectedMethodPolicy $protectedMethodPolicy = null,
31	        ?NonPublicMethodErrorBuilder $errorBuilder = null,
32	    ) {
33	        $this->protectedMethodPolicy = $protectedMethodPolicy ?? new ProtectedMethodPolicy();
34	        $this->errorBuilder = $errorBuilder ?? new NonPublicMethodErrorBuilder();
35	    }
36	
37	    /**
38	     * @return class-string<\PhpParser\Node\Stmt\ClassLike>
39	     */
40	    public function getNodeType(): string
41	    {
42	        return \PhpParser\Node\Stmt\ClassLike::class;
43	    }
44	
45	    /**
46	     * @param \PhpParser\Node\Stmt\ClassLike $node
47	     * @return list<IdentifierRuleError>
48	     */
49	    public function processNode(\PhpParser\Node $node, Scope $scope): array
50	    {
51	        $errors = [];
52	
53	        foreach ($node->getMethods() as $method) {
54	            if ($method->isPrivate()) {
55	                $errors[] = $this->errorBuilder->privateMethod($method, $node, $scope);
56	                continue;
57	            }
58	
59	            if (!$method->isProtected()) {
60	                continue;
61	            }
62	
63	            if ($this->protectedMethodPolicy->allows($node, $method)) {
64	                continue;
65	            }
66	
67	            $errors[] = $this->errorBuilder->protectedMethod($method, $node, $scope);
68	        }
69	
70	        return $errors;
71	    }
72	}
