        if ($node instanceof \PhpParser\Node\Expr\New_) {
            return $this->methodErrors($this->classesOf($node->class, $scope), '__construct', $callerNamespace, $node->getStartLine());
        }

        if ($node instanceof \PhpParser\Node\Expr\StaticCall) {
            return $this->methodErrors($this->classesOf($node->class, $scope), $this->nameOf($node->name), $callerNamespace, $node->getStartLine());
        }

        if ($node instanceof \PhpParser\Node\Expr\MethodCall || $node instanceof \PhpParser\Node\Expr\NullsafeMethodCall) {
            return $this->methodErrors($this->classesOf($node->var, $scope), $this->nameOf($node->name), $callerNamespace, $node->getStartLine());
        }

        if ($node instanceof \PhpParser\Node\Expr\StaticPropertyFetch) {
            return $this->propertyErrors($this->classesOf($node->class, $scope), $this->nameOf($node->name), $callerNamespace, $node->getStartLine());
        }

        if ($node instanceof \PhpParser\Node\Expr\PropertyFetch || $node instanceof \PhpParser\Node\Expr\NullsafePropertyFetch) {
            return $this->propertyErrors($this->classesOf($node->var, $scope), $this->nameOf($node->name), $callerNamespace, $node->getStartLine());
        }

        if ($node instanceof \PhpParser\Node\Expr\ClassConstFetch) {
            return $this->constantErrors($this->classesOf($node->class, $scope), $this->nameOf($node->name), $callerNamespace, $node->getStartLine());
        }

        if ($node instanceof \PhpParser\Node\Expr\Instanceof_) {
            return $this->classErrors($this->classesOf($node->class, $scope), $callerNamespace, $node->getStartLine());
        }

        return [];
    }

